<script setup>
import {Head,router} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import EmptyState from '../Components/EmptyState.vue';
const props=defineProps({entries:Array,comparison:Object});const select=(side,value)=>router.get('/rivalries',{left:side==='left'?value:props.comparison.left.id,right:side==='right'?value:props.comparison.right.id});
</script>
<template><Head title="Rivalries"/><AppLayout><p class="label">Head to head</p><h1 class="mt-2 text-4xl font-black">Settle it with numbers.</h1><p class="mt-2 text-[#718078]">Compare any two Mandem managers across the season.</p><div v-if="comparison" class="mt-8"><div class="grid items-stretch gap-4 lg:grid-cols-[1fr_auto_1fr]"><section class="card p-7"><select :value="comparison.left.id" @change="select('left',$event.target.value)" class="field"><option v-for="e in entries" :value="e.id">{{e.manager_name}}</option></select><h2 class="mt-6 text-3xl font-black">{{comparison.left.team_name}}</h2><div class="mt-7 grid grid-cols-3 gap-3"><div><span class="label">Total</span><b class="block text-2xl">{{comparison.left.total_points}}</b></div><div><span class="label">GW wins</span><b class="block text-2xl">{{comparison.score.left}}</b></div><div><span class="label">Average</span><b class="block text-2xl">{{comparison.metrics.left_average}}</b></div></div></section><div class="grid place-items-center"><span class="grid size-20 place-items-center rounded-full bg-[#143c2b] text-2xl font-black text-[#f4d35e]">{{comparison.score.left}}–{{comparison.score.right}}</span></div><section class="card p-7 text-right"><select :value="comparison.right.id" @change="select('right',$event.target.value)" class="field"><option v-for="e in entries" :value="e.id">{{e.manager_name}}</option></select><h2 class="mt-6 text-3xl font-black">{{comparison.right.team_name}}</h2><div class="mt-7 grid grid-cols-3 gap-3"><div><span class="label">Average</span><b class="block text-2xl">{{comparison.metrics.right_average}}</b></div><div><span class="label">GW wins</span><b class="block text-2xl">{{comparison.score.right}}</b></div><div><span class="label">Total</span><b class="block text-2xl">{{comparison.right.total_points}}</b></div></div></section></div>
<div class="mt-6 grid gap-6 lg:grid-cols-2"><section class="card p-7"><h2 class="text-xl font-black">Gameweek record</h2><div class="mt-5 space-y-3"><div v-for="g in comparison.timeline" class="grid grid-cols-[3rem_1fr_auto_1fr] items-center gap-3 text-sm"><span class="label">GW{{g.gameweek}}</span><div class="h-2 overflow-hidden rounded-full bg-[#e7ebe7] text-right dark:bg-[#20332a]"><div class="ml-auto h-full bg-[#1d7650]" :style="{width:`${g.left/Math.max(1,g.left,g.right)*100}%`}"></div></div><b>{{g.left}}–{{g.right}}</b><div class="h-2 overflow-hidden rounded-full bg-[#e7ebe7] dark:bg-[#20332a]"><div class="h-full bg-[#f4d35e]" :style="{width:`${g.right/Math.max(1,g.left,g.right)*100}%`}"></div></div></div><p v-if="!comparison.timeline.length" class="text-sm text-[#718078]">Head-to-head history begins after both managers complete a gameweek.</p></div></section><section class="card p-7"><h2 class="text-xl font-black">Squad DNA</h2><div class="mt-5"><span class="label">Shared core · {{comparison.common.length}}</span><div class="mt-2 flex flex-wrap gap-2"><span v-for="p in comparison.common" class="rounded-full bg-[#e7eee8] px-3 py-1 text-xs dark:bg-[#193026]">{{p}}</span></div></div><div class="mt-6 grid grid-cols-2 gap-5"><div><span class="label">{{comparison.left.manager_name}} only</span><p class="mt-2 text-sm leading-7">{{comparison.left_unique.join(', ')||'None'}}</p></div><div class="text-right"><span class="label">{{comparison.right.manager_name}} only</span><p class="mt-2 text-sm leading-7">{{comparison.right_unique.join(', ')||'None'}}</p></div></div><div class="mt-6 grid grid-cols-2 gap-4 border-t border-black/5 pt-5 text-sm dark:border-white/10"><p>Bench points: <b>{{comparison.metrics.left_bench}} vs {{comparison.metrics.right_bench}}</b></p><p class="text-right">Hits: <b>{{comparison.metrics.left_hits}} vs {{comparison.metrics.right_hits}}</b></p></div></section></div></div><EmptyState v-else class="mt-8" title="Not enough managers yet" text="Rival comparisons appear when at least two league entries have been imported."/></AppLayout></template>
